export function buildGovernanceEvidenceBundleCompleteness({manifest,requiredClasses}){let have=new Set(manifest.entries.map(x=>x.evidenceClass)),required=[...new Set(requiredClasses)].sort(),missing=required.filter(x=>!have.has(x)),extra=[...have].filter(x=>!required.includes(x)).sort();return Object.freeze({kind:"governance-evidence-bundle-completeness/v1",manifestHash:manifest.manifestHash,required:Object.freeze(required),missing:Object.freeze(missing),extra:Object.freeze(extra),complete:!missing.length})}
